using AcademyDesk.Api.Data;using AcademyDesk.Api.Domain.Entities;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcademyDesk.Api.Controllers;
[ApiController][Route("api/academies/{academyId:guid}/assignment-submissions")]
public sealed class AssignmentSubmissionsController(AcademyDeskDbContext db):ControllerBase{[HttpGet]public async Task<ActionResult<IReadOnlyList<AssignmentSubmission>>>List(Guid academyId,Guid? assignmentId,CancellationToken t){var q=db.AssignmentSubmissions.AsNoTracking().Where(x=>x.AcademyId==academyId);if(assignmentId.HasValue)q=q.Where(x=>x.AssignmentId==assignmentId);return Ok(await q.OrderByDescending(x=>x.SubmittedAtUtc).ToListAsync(t));}[HttpPost]public async Task<ActionResult<AssignmentSubmission>>Submit(Guid academyId,AssignmentSubmission x,CancellationToken t){if(!await db.Assignments.AnyAsync(a=>a.Id==x.AssignmentId&&a.AcademyId==academyId,t))return BadRequest();x.Id=Guid.NewGuid();x.AcademyId=academyId;db.AssignmentSubmissions.Add(x);await db.SaveChangesAsync(t);return Ok(x);}[HttpPatch("{id:guid}/review")]public async Task<ActionResult<AssignmentSubmission>>Review(Guid academyId,Guid id,ReviewRequest r,CancellationToken t){var x=await db.AssignmentSubmissions.SingleOrDefaultAsync(x=>x.Id==id&&x.AcademyId==academyId,t);if(x is null)return NotFound();x.TeacherFeedback=r.Feedback;x.Status="Reviewed";await db.SaveChangesAsync(t);return Ok(x);}}
public sealed record ReviewRequest(string? Feedback);
